# Two objects are inside the pan, and the nearer paper object is held.
# I will place it, then use a forward-tilted grasp to reach the farther paper object.
def quick_pose(side,target,grip,steps=10):
    global obs,terminated,truncated
    s=get_observation()['state']
    act={k:list(s[k]) for k in ['left_ee_pose','right_ee_pose','left_ee_joint_state','right_ee_joint_state']}
    act[side+'_ee_pose']=target
    act[side+'_ee_joint_state']=[grip]
    count=0
    for i in range(steps):
        obs,reward,terminated,truncated,info=step(act)
        if terminated or truncated:
            return False
        p=obs['state'][side+'_ee_pose']
        err=sum((float(p[j])-target[j])**2 for j in range(3))**0.5
        qe=min(sum((float(p[j])-target[j])**2 for j in range(3,7)),sum((float(p[j])+target[j])**2 for j in range(3,7)))**0.5
        count=count+1 if err<0.004 and qe<0.04 else 0
        if count>=2:
            break
    print('quick',side,i+1,list(p))
    return err<0.006 and qe<0.05
release_pose=[0.025,-0.195,1.01]+qdown
if quick_pose('right',release_pose,0):
    if servo_line('right',release_pose,1,max_steps=14,settle=12):
        if quick_pose('right',[0.103,-0.025,1.0]+qtilt,1):
            if quick_pose('right',[0.103,-0.025,0.915]+qtilt,1):
